const { nombre, email, telefono, fecha, hora } = $input.first().json;

const mesesEs = {
  'enero':0,'febrero':1,'marzo':2,'abril':3,'mayo':4,'junio':5,
  'julio':6,'agosto':7,'septiembre':8,'octubre':9,'noviembre':10,'diciembre':11
};
const mesesEn = {
  'january':0,'february':1,'march':2,'april':3,'may':4,'june':5,
  'july':6,'august':7,'september':8,'october':9,'november':10,'december':11
};

let day, month, year;
const f = (fecha||'').toLowerCase().replace(/[,.]/g,'');
for (const p of f.split(/\s+/)) {
  if (/^\d{4}$/.test(p)) year = parseInt(p);
  else if (/^\d{1,2}$/.test(p) && !day) day = parseInt(p);
  else if (mesesEs[p] !== undefined) month = mesesEs[p];
  else if (mesesEn[p] !== undefined) month = mesesEn[p];
}

if (!day || month === undefined || !year) {
  const iso = new Date(fecha);
  if (!isNaN(iso)) { day=iso.getDate(); month=iso.getMonth(); year=iso.getFullYear(); }
  else return [{ json: { success:false, result:'No pude interpretar la fecha: '+fecha } }];
}

let h=10, m=0;
const t = (hora||'10:00 AM').toLowerCase();
const tm = t.match(/(\d{1,2})[:]?(\d{2})?\s*(am|pm)?/);
if (tm) {
  h=parseInt(tm[1]); m=parseInt(tm[2]||'0');
  if (tm[3]==='pm' && h<12) h+=12;
  if (tm[3]==='am' && h===12) h=0;
}

const pad = n => String(n).padStart(2,'0');
const localStart = `${year}-${pad(month+1)}-${pad(day)}T${pad(h)}:${pad(m)}:00`;
const endH = h + Math.floor((m+15)/60);
const endM = (m+15) % 60;
const localEnd = `${year}-${pad(month+1)}-${pad(day)}T${pad(endH)}:${pad(endM)}:00`;

const dias   = ['domingo','lunes','martes','miércoles','jueves','viernes','sábado'];
const meses  = ['enero','febrero','marzo','abril','mayo','junio','julio','agosto','septiembre','octubre','noviembre','diciembre'];
const d = new Date(year, month, day);
const displayFecha = `${dias[d.getDay()]} ${day} de ${meses[month]} de ${year}`;
const displayHora  = h < 12
  ? `${pad(h===0?12:h)}:${pad(m)} AM`
  : `${pad(h===12?12:h-12)}:${pad(m)} PM`;

return [{ json: { nombre, email, telefono, localStart, localEnd, displayFecha, displayHora } }];

const events = $input.all();
const parsed = $('Parse Fecha Hora').first().json;
return [{ json: { ...parsed, eventCount: events.length, slotAvailable: events.length === 0 } }];

