parameters.jsCode:
const { nombre, displayFecha, displayHora, localStart } = $json;

const base = new Date(localStart);
const slots = [];
const businessHours = [9,10,11,14,15,16];

let checkDate = new Date(base);
let daysChecked = 0;

while (slots.length < 3 && daysChecked < 14) {
  if (slots.length > 0 || daysChecked > 0) {
    checkDate.setDate(checkDate.getDate() + 1);
  }
  daysChecked++;
  const dow = checkDate.getDay();
  if (dow === 0 || dow === 6) continue;
  for (const h of businessHours) {
    if (h === base.getHours() && checkDate.getDate() === base.getDate()) continue;
    const dias  = ['domingo','lunes','martes','miércoles','jueves','viernes','sábado'];
    const meses = ['enero','febrero','marzo','abril','mayo','junio','julio','agosto','septiembre','octubre','noviembre','diciembre'];
    const ampm  = h < 12 ? `${h}:00 AM` : `${h === 12 ? 12 : h - 12}:00 PM`;
    slots.push(`${dias[checkDate.getDay()]} ${checkDate.getDate()} de ${meses[checkDate.getMonth()]} a las ${ampm}`);
    if (slots.length >= 3) break;
  }
}

return [{ json: {
  success: false,
  result: `El horario del ${displayFecha} a las ${displayHora} no está disponible. Te ofrezco estas alternativas:\n\n1. ${slots[0]}\n2. ${slots[1]}\n3. ${slots[2]}\n\n¿Cuál te viene mejor?`
}}];
